mapper.select:
SELECT t.ticket_id, t.tenant_id, t.customer_id, t.customer_name, t.ticket_no, t.ticket_title, t.severity, t.issue_type, t.owner_id, t.owner_name, t.opened_time, t.resolved_time, t.due_time, t.description, t.solution, t.portal_contact_id, t.portal_solution, t.portal_solution_time, t.attachment_url, t.status, t.sla_policy_id, t.first_response_due, t.resolution_due, t.first_response_time, t.first_response_minutes, t.resolution_minutes, t.sla_paused_minutes, t.pause_start_time, t.sla_status, t.response_breached_flag, t.resolution_breached_flag, t.version, t.deleted, t.create_by, t.create_time, t.update_by, t.update_time, CASE WHEN t.portal_contact_id IS NOT NULL AND t.owner_id = #{currentUserId} THEN #{currentDeptId} ELSE c.dept_id END AS scope_dept_id, CASE WHEN t.portal_contact_id IS NOT NULL AND t.owner_id = #{currentUserId} THEN t.owner_id ELSE c.owner_id END AS scope_owner_id FROM crm_service_ticket t INNER JOIN crm_customer c ON c.customer_id = t.customer_id AND c.deleted = '0' WHERE t.deleted = '0' AND t.portal_contact_id IS NOT NULL AND t.owner_id IS NULL AND t.status = 'OPEN' AND t.sla_policy_id = #{query.slaPolicyId} AND t.sla_status = #{query.slaStatus} AND t.owner_id = #{query.ownerId}
AND t.customer_id = #{query.customerId}
AND t.ticket_title LIKE CONCAT('%', #{query.ticketTitle}, '%')
AND t.severity = #{query.severity}
AND t.status = #{query.status}
ORDER BY t.update_time DESC



SELECT ticket.*,
    CASE WHEN ticket.portal_contact_id IS NOT NULL AND ticket.owner_id = #{currentUserId}
        THEN #{currentDeptId} ELSE customer.dept_id END AS scope_dept_id,
    CASE WHEN ticket.portal_contact_id IS NOT NULL AND ticket.owner_id = #{currentUserId}
        THEN ticket.owner_id ELSE customer.owner_id END AS scope_owner_id
FROM crm_service_ticket ticket INNER JOIN crm_customer customer ON customer.customer_id = ticket.customer_id
  AND customer.tenant_id = ticket.tenant_id AND customer.deleted = 0
WHERE ticket.deleted = 0 AND ticket.sla_policy_id IS NOT NULL
AND ticket.sla_policy_id = #{query.policyId}
AND ticket.owner_id = #{query.ownerId}
AND ticket.severity = #{query.severity}
AND ticket.opened_time >= #{query.start}
AND ticket.opened_time < DATE_ADD(#{query.end}, INTERVAL 1 DAY)
